func drive(delta, throttle, steer, terrain):
  if terrain == "^": boosted = 2.0
  # 水坑速度 ×0.5，加速板 ×1.5
  var factor := 0.5 if terrain == "~" \
      else (1.5 if boosted > 0 else 1.0)
  speed = move_toward(speed,
      throttle * cfg.max_speed * factor, delta * 12)
  rotate_y(-steer * cfg.turn_speed * delta)
  velocity = -transform.basis.z * speed
  move_and_slide()          # 撞到牆會自己停下
  # 每走 0.28 公尺留一個軌跡記號
  if cfg.trail.show and position.distance_to(last_trail) > 0.28:
    var col := Color(cfg.trail.color)
    if cfg.trail.rainbow:
      col = Color.from_hsv(fmod(Time.get_ticks_msec() / 4000.0, 1), 0.8, 1)

